# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
W=[
E('cover','/ˈkʌvə(r)/','盖住；包含；报道；足够支付；封面、盖子','想象一块布铺过去：能遮住东西，也能用它的范围表示事情管到哪里。','借自古法语 covrir，向前是拉丁 cooperire，其中 co- 加强语气，operire 表示遮盖。现代英语里不拆成 co + ver。',[['拉丁 operire → cooperire','遮盖 → 盖住、覆盖'],['晚期拉丁 coperire → 古法语 covrir','遮盖、保护'],['中古英语 coveren → cover','覆盖；后来扩展到范围、报道和支付等']],'cover the bowl 是把碗盖住；cover three topics 是把三个主题纳入讲解范围；cover the cost 是钱足够把这笔开销全部包住。记者 cover an event，则负责把这件事报道出来。名词 a cover 可以是盖子、封面；a cover of a song 是另一位歌手的翻唱，这个固定用法单独记，不必硬套盖布。','cover A with B：用 B 盖住 A；cover the cost；cover a story；a book cover。','cover 强调遮盖或范围；include 强调某项在其中；report 直接说报道。cover 和 recover 恢复不能简单理解为盖上与再盖上。',('Cover the bowl with a clean cloth.','用一块干净的布盖住碗。'),('The course covers the basics of photography.','这门课程讲授摄影的基础知识。'),('The fee covers lunch and transport.','这笔费用包含午餐和交通。'),sources=['https://www.etymonline.com/word/cover','https://en.wiktionary.org/wiki/cover#English']),
E('uncover','/ʌnˈkʌvə(r)/','揭开；揭露；查明','把挡在前面的那层东西拿掉，原先看不到的东西就露出来了。','英语 un- 撤去、反向 + cover 盖住。在有记载的早期英语中，揭露事实的比喻义反而比移去覆盖物的实物义更早出现。',[['英语 cover','盖住、隐藏'],['中古英语 un- + coveren → uncover','揭露；也表示去掉覆盖物']],'uncover a painting 可以是把罩着画的布揭掉；uncover a problem 则像把问题外面的遮挡去掉，让它显现。这个画面帮助理解意思，不代表每个义项都按实物到抽象的顺序出现。','uncover evidence；uncover the truth；uncover a hidden problem。','discover 侧重发现之前不知道的东西；uncover 特别容易让人想到原先藏着、被掩盖或不易察觉的东西。两者在发现证据等语境中可以重合。',('She uncovered the painting for the visitors.','她揭开罩在画上的布，让参观者观看。'),('The review uncovered several errors in the report.','复查发现了报告中的几处错误。'),sources=['https://www.etymonline.com/word/uncover']),
E('discover','/dɪˈskʌvə(r)/','发现；了解到','原先在你的视野之外，现在第一次被你看见或弄明白了。','今天可借 dis- 去掉 + cover 遮盖理解，但英语整体借自古法语 descovrir；它的前身是 discooperire，不是在现代英语里临时拼出的词。',[['拉丁 cooperire；后来的 discooperire','遮盖；去掉遮盖'],['古法语 descovrir → 中古英语 discoveren','揭开、暴露、透露'],['英语 discover','逐渐以发现先前不知道的事物为主要意思']],'古老的画面是揭掉遮挡，现代重点落在新的认识上。你 discover a café，只是你第一次找到这家店，不是人类第一次知道它存在。discover that 后面可直接接你刚了解到的事实。','discover a place；discover a talent；discover that…；discover how…。','discover 通常面对已经存在但先前未知的东西；invent 是创造出新的东西。发现一种现象与发明一台机器，动作不同。',('We discovered a quiet café near the station.','我们在车站附近发现了一家安静的咖啡馆。'),('I discovered that the file had been saved in another folder.','我发现文件被存到了另一个文件夹里。'),sources=['https://www.etymonline.com/word/discover']),
E('discovery','/dɪˈskʌvəri/','发现这件事；发现的成果','把“我发现了”变成可以谈论的一件事或一项成果。','由英语 discover 形成名词。学习时记 discover → discovery；词尾 -y 构成名词，不把里面的 every 或 cover 当作独立的新意思。',[['英语 discover','发现原先不知道的东西'],['英语 discovery','发现这一过程、事件；也指发现所得的东西']],'the discovery of a cave 可以说发现洞穴这件事；a remarkable discovery 可以说一项重要发现。它不只属于科学新闻，你找到一份旧日记也可以叫 a discovery。','make a discovery；the discovery of…；a surprising discovery；scientific discovery。','discovery 是新发现，invention 是新发明；evidence 是支持判断的证据，不等于发现本身。',('The discovery of the letters changed our understanding of her life.','这些信件的发现改变了我们对她生平的认识。'),('The team made an unexpected discovery during the survey.','团队在调查过程中有了意外发现。'),sources=['https://www.etymonline.com/word/discovery','https://en.wiktionary.org/wiki/discovery#English']),
E('covering','/ˈkʌvərɪŋ/','覆盖物；覆盖层','盖在外面的那一层，先看它起什么作用，不限定它是什么材料。','cover + -ing 在这里形成名词；同样的形式也能是动词现在分词，要看句子。',[['英语 cover','盖住、覆盖'],['英语 covering','覆盖动作；作为名词指盖在上面的东西']],'a covering of snow 是一层雪，a protective covering 是保护层，可以是布、塑料或别的材料。a covering 往往指某种实体覆盖物；coverage 则多谈覆盖范围、程度或报道。','a thin covering；a protective covering；a covering of dust。','cover 常指具体的盖子、套子或封面；covering 更容易突出铺在表面的材料或一层东西，范围有重合。',('A thin covering of snow lay on the roof.','屋顶上覆盖着薄薄一层雪。'),('Remove the protective covering before using the screen.','使用屏幕前先揭掉保护层。'),sources=['https://en.wiktionary.org/wiki/covering#English']),
E('undiscovered','/ˌʌndɪˈskʌvəd/','尚未被发现的','东西已经在那里，只是还没有进入人的视野。','un- 尚未、不 + discovered 被发现的。这里 un- 否定已发现状态，和 uncover 的撤去覆盖不一样。',[['英语 discover → discovered','发现 → 被发现的'],['英语 un- + discovered','尚未被发现的']],'undiscovered species 是尚未被发现的物种，undiscovered talent 是还没被人注意到的才能。它不表示不存在，也不一定表示有人故意隐藏。','an undiscovered species；undiscovered talent；remain undiscovered。','hidden 可能是被藏起或被挡住；undiscovered 只说尚未被发现。unknown 更广，只是未知或不知名。',('The manuscript remained undiscovered for decades.','这份手稿几十年来一直未被发现。'),('The competition gives undiscovered musicians a chance to perform.','这项比赛给尚未受到关注的音乐人提供表演机会。'),sources=['https://en.wiktionary.org/wiki/undiscovered#English']),
E('coverage','/ˈkʌvərɪdʒ/','覆盖范围；新闻报道；保障范围','不是外面盖着什么，而是这张“覆盖网”伸到了哪里。','cover + -age 名词结尾。这个形式早期曾用于集市摊位费用，后来消失；现代用法在二十世纪初从保障范围重新发展，不能把所有古义强串成一条直线。',[['英语 cover + -age','由覆盖形成名词'],['现代 coverage','保障范围；进一步用于报道、信号等覆盖']],'mobile coverage 看哪里能收到信号；media coverage 看媒体对一件事的报道；insurance coverage 指保单提供的保障范围。把共同点记成管到哪里、覆盖多少，就比背三个互不相干的中文词容易。','network coverage；live coverage；media coverage；extensive coverage。','covering 多是覆盖物；coverage 多是范围、程度或报道内容。通常作不可数名词，说 extensive coverage，不说 many coverages 来表示大量报道。',('Mobile coverage is poor in this valley.','这个山谷里的手机信号覆盖很差。'),('The channel provided live coverage of the final.','这个频道对决赛进行了现场直播。'),sources=['https://www.etymonline.com/word/coverage','https://en.wiktionary.org/wiki/coverage#English']),
E('covert','英 /ˈkʌvət/；美常 /ˈkoʊvɜːrt/','秘密的；隐蔽的；不公开的','事情在做，但上面盖着一层，让外人看不见。','来自古法语 covert，原是 covrir 遮盖的过去分词，相当于被盖住的。不是英语 cover 随意加一个 t。',[['古法语 covrir → covert','遮盖 → 被遮盖的、隐藏的'],['英语 covert','隐蔽的、秘密进行的']],'covert support 是暗中支持，covert action 是不公开进行的行动。重点是不让行动或意图被看出来，不是声音小或环境安静。','covert action；covert support；covert surveillance。','overt 是公开、明显的；covert 是隐藏、不公开的。二者意思相对，但不能把 covert 硬拆成 c + overt。',('The group received covert support from wealthy donors.','这个团体得到了一些富裕捐助者的暗中支持。'),('The novel follows a covert operation that goes wrong.','这部小说讲述了一次出了差错的秘密行动。'),sources=['https://www.etymonline.com/word/covert','https://en.wiktionary.org/wiki/covert#English']),
E('covertly','英 /ˈkʌvətli/；美常 /ˈkoʊvɜːrtli/','秘密地；暗中地','动作照常发生，只是刻意避开别人的注意。','covert 隐蔽的 + -ly 副词结尾。',[['英语 covert','不公开的、隐蔽的'],['英语 covertly','以不让人察觉的方式行动']],'covertly fund a project 是暗中资助一个项目，重点是资助关系没有公开。它比 quietly 更强调隐瞒：quietly 可以只是低调、不声张，不一定刻意隐藏。','covertly support；covertly fund；act covertly。','covertly 说行动方式；confidentially 常说信息只在限定的人之间传递。',('The company covertly funded the campaign.','这家公司暗中资助了这场宣传活动。'),('In the story, the two rivals covertly exchange information.','故事中，这两个对手暗中交换情报。'),sources=['https://www.etymonline.com/word/covert','https://en.wiktionary.org/wiki/covertly#English']),
E('undercover','英 /ˌʌndəˈkʌvə/；美 /ˌʌndərˈkʌvər/','秘密调查的；卧底的；以隐蔽身份活动','人在现场，真正的身份和目的却藏在掩护下面。','由 under cover 在掩护之下这个短语形成。早期可说受掩护，后来发展为秘密活动，尤其隐藏真实身份的调查。',[['英语 under + cover','在掩护之下'],['英语 undercover','受掩护；后来用于秘密调查和隐蔽身份']],'an undercover reporter 会以不暴露记者身份的方式调查；go undercover 是进入这样的隐蔽身份状态。这个词可以作形容词，也可放在 work、go 等动词之后。','an undercover officer；undercover work；go undercover；work undercover。','covert 泛指隐蔽的；undercover 常涉及调查者隐藏身份或目的。屋顶下避雨通常写 under cover 两个词，不用这个合写的调查义。',('The film is about an undercover officer.','这部电影讲述一名卧底警员的故事。'),('The journalist worked undercover for the investigation.','这名记者为这次调查隐瞒了真实身份。'),sources=['https://www.etymonline.com/word/undercover','https://en.wiktionary.org/wiki/undercover#English']),
E('curfew','英 /ˈkɜːfjuː/；美 /ˈkɜːrfjuː/','宵禁；规定必须回家的时间','钟一响，该收火、结束外面的活动、回去了。','来自古法语 cuevrefeu，字面是盖住火：cuevre 来自 covrir 盖住，feu 是火。后来经盎格鲁法语进入英语。',[['古法语 cuevre + feu → cuevrefeu','盖住 + 火 → 提醒熄火或收火的信号'],['盎格鲁法语 coeverfu → 英语 curfew','晚间收火的钟声、规定时间'],['现代英语 curfew','限制外出的时间；也指家中规定的回家时间']],'早年的画面是夜里收火，避免炉火无人看管。现代 curfew 可以是某段时间不得外出的规定，也可以是父母给孩子定的回家时间。a ten o’clock curfew 在家庭语境里就是十点前得回家。','impose a curfew；lift a curfew；a curfew begins；be home before curfew。','bedtime 是睡觉时间，curfew 常是必须回家或不得在外活动的时间，两者不一定相同。few 在这里不表示少。',('The city lifted the curfew the following morning.','这座城市在第二天早晨解除了宵禁。'),('Her parents set a ten o’clock curfew.','她父母规定她必须在十点前回家。'),sources=['https://www.etymonline.com/word/curfew','https://en.wiktionary.org/wiki/curfew#English'])
]
ROOT=dict(id='C0899',meaning='盖住；遮住',core='OPER = COVER',image='一块布盖住东西；揭开后看见，是 discover；藏在覆盖下，是 covert；盖住头成了 kerchief，盖住炉火成了 curfew。',intro='拉丁 operire 表示关闭、遮盖，cooperire 加强了盖住的意思。经过法语，今天最熟悉的词形是 cover。这一族把日常盖东西、隐藏消息、发现事物连在一起。',forms='operire → cooperire → 古法语 covrir → cover。covert 来自法语过去分词；discover 从法语整体借入；uncover 是英语加 un-。这些词共享来源，但形成的时代和方式不同。',branches=[['盖住及覆盖范围','cover','covering','coverage'],['揭开并发现','uncover','discover','discovery','undiscovered'],['隐蔽行动','covert','covertly','undercover'],['旧复合词保留的生活画面','kerchief','handkerchief','curfew']],contrasts='这里的 oper- 是遮盖，与 operate、operation 所走的工作词源线分开学。词根相同不等于每个词都能逐字翻译：coverage 看范围，covering 看覆盖物，discover 看新的认识。',practice='The reporter worked undercover and uncovered evidence that received wide media coverage.\n\n这名记者隐瞒身份展开调查，发现的证据随后得到媒体广泛报道。',words=[x['word'] for x in W]+['kerchief','handkerchief'],exclude={w:'专门生物形态术语，暂不扩展。' for w in ['operculum','opercular','interoperculum','operculiform']})
ROOT['branches']=[[x[0],'；'.join(x[1:])] for x in ROOT['branches']]
if __name__=='__main__':
 for name,data in [('roots_oper',[ROOT]),('words_oper',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
